/*
 * ESP32 Dual-Core FreeRTOS Blink
 *
 * Core 0: Blinks the onboard LED (GPIO2) at 500ms interval
 * Core 1: Prints a counter to Serial every 1000ms
 *
 * Demonstrates xTaskCreatePinnedToCore() to pin tasks
 * to specific CPU cores on the ESP32.
 */

#include <freertos/FreeRTOS.h>
#include <freertos/task.h>

// Task running on Core 0 — LED blink
void core0BlinkTask(void *pvParameters) {
  while (true) {
    digitalWrite(LED_BUILTIN, HIGH);
    Serial.println("[Core 0] LED ON");
    vTaskDelay(500);

    digitalWrite(LED_BUILTIN, LOW);
    Serial.println("[Core 0] LED OFF");
    vTaskDelay(500);
  }
}

// Task running on Core 1 — Serial counter
void core1CounterTask(void *pvParameters) {
  int count = 0;
  while (true) {
    Serial.print("[Core 1] Counter: ");
    Serial.println(count++);
    vTaskDelay(1000);
  }
}

void setup() {
  Serial.begin(9600);
  Serial.println("ESP32 Dual-Core FreeRTOS Demo");
  Serial.println("============================");

  pinMode(LED_BUILTIN, OUTPUT);

  // Create task on Core 0
  xTaskCreatePinnedToCore(
    core0BlinkTask,   // Task function
    "BlinkTask",      // Task name
    2048,             // Stack size
    NULL,             // Parameters
    1,                // Priority
    NULL,             // Task handle
    0                 // Core ID (0 = Core 0)
  );

  // Create task on Core 1
  xTaskCreatePinnedToCore(
    core1CounterTask, // Task function
    "CounterTask",    // Task name
    2048,             // Stack size
    NULL,             // Parameters
    1,                // Priority
    NULL,             // Task handle
    1                 // Core ID (1 = Core 1)
  );

  Serial.println("Tasks created. Scheduler starting...");
}

void loop() {
  // loop() runs on Core 1 by default
  vTaskDelay(1000);
}
